  /* Global focus-visible ring — WCAG 2.1 AA compliant */
  :focus-visible {
    outline: 2px solid #21cfff;
    outline-offset: 3px;
  }

  /* Remove outline for mouse users, keep for keyboard */
  :focus:not(:focus-visible) {
    outline: none;
  }

  /* Screen-reader only utility */
  .sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border-width: 0;
  }
}

