@media screen and (max-width: 767px) {
  .nav-dropdown-arrow {
    color: var(--color-brand-cyan);
    -webkit-text-fill-color: transparent;
    background-image: linear-gradient(#21cfff, #019ae6);
    -webkit-background-clip: text;
    background-clip: text;
  }

  .banner-content {
    flex-direction: column;
    text-align: center;
    gap: 4px;
  }

  .beta-link {
    background-color: transparent;
    border: none;
    text-decoration: underline;
    padding: 0;
    font-size: 14px;
  }

  .nav-23-dropdown-link {
    background-color: var(--blue, #082753);
    color: var(--white, #fff);
    border-bottom: 1px solid rgba(255, 255, 255, 0.04);
    border-radius: 0;
    padding: 12px 0;
  }

  .nav-23-dropdown-link:hover {
    background-color: var(--blue, #082753);
  }

  .nav-23-dropdown-arrow {
    color: var(--color-brand-cyan);
  }

  .nav-23-dropdown-links {
    grid-column-gap: 0px;
    grid-row-gap: 0px;
  }

  .navbar {
    position: static;
  }

  .nav-23-link {
    border-bottom: 1px solid rgba(255, 255, 255, 0.04);
    border-radius: 0;
    align-self: stretch;
    padding: 12px 0;
    /* WCAG AA fix: mobile menu bg is #082753 (navy); default color #000 = ratio 1.43 (fail).
       Override to white for sufficient contrast on navy. */
    color: #fff;
  }

  .nav-23-dropdown-card {
    border-radius: 0;
  }

  .nav-23-menu {
    z-index: 11;
    background-color: var(--color-text-primary);
    border-radius: 0;
    flex-flow: column;
    align-self: auto;
    width: auto;
    height: auto;
    margin: 0;
    padding: 10px 4%;
    inset: 0%;
    top: 100%;
  }

  .nav-23-dropdown {
    align-self: stretch;
  }

